const intent = $json.intent;
const urgency = $json.urgency;
const confidence = 0.85; // TODO: calcular desde LLM

let recommendedRole = 'agent';
let priority = 5;
let autoSendRecommended = false;

if (intent === 'venta' && confidence > 0.8) {
  recommendedRole = 'admin';
  priority = 8;
} else if (urgency === 'critica') {
  recommendedRole = 'admin';
  priority = 10;
} else if (intent === 'soporte' && urgency === 'alta') {
  priority = 7;
}

if (urgency === 'baja' && confidence > 0.9 && intent !== 'venta') {
  autoSendRecommended = true;
}

return {
  job_id: $('Verify Signature').item.json.data.job_id,
  status: 'completed',
  output: {
    intent: $json.intent,
    urgency: $json.urgency,
    sentiment: $json.sentiment,
    summary: $json.summary,
    suggested_reply: $json.text || $json.content,
    confidence: confidence,
    language: $json.language || 'es',
    entities: $json.entities || {},
    routing: {
      recommended_role: recommendedRole,
      priority: priority,
      auto_send_recommended: autoSendRecommended
    }
  },
  meta: {
    n8n_execution_id: $execution.id,
    model: 'gpt-4o',
    prompt_version: '1.0',
    latency_ms: Date.now() - $execution.startedAt
  }
};
